Bash(cd /f/AISTUDIO/nova-dark-messenger && cat > .e2e/probe2.mjs <<'EOF'
import { chromium } from 'playwright-core';
const exe = process.env.USERPROFILE + '/AppData/Local/ms-playwright/chromium-1255/chrome-win64/chrome.exe';
const browser = await chromium.launch\({ executablePath: exe, headless: true }\);
const ctx = await browser.newContext\({ viewport: { width: 390, height: 844 } }\);
const page = await ctx.newPage\(\);
page.on\('console', \(m\) => { if \(m.type\(\) === 'error' || m.type\(\) === 'warning'\) console.log\('CONSOLE', m.type\(\), m.text\(\).slice\(0, 600\)\); }\);
page.on\('pageerror', \(e\) => console.log\('PAGEERROR', e.message, '\\n', \(e.stack||''\).split\('\\n'\).slice\(0,12\).join\('\\n'\)\)\);
await page.goto\('http://localhost:3000/', { waitUntil: 'domcontentloaded' }\);
await page.waitForTimeout\(2500\);

const wiz = page.getByTestId\('onboarding-wizard'\);
await wiz.getByRole\('button', { name: 'Create my identity' }\).click\(\);
await page.getByRole\('textbox', { name: 'Choose a nickname' }\).fill\('Tester'\);
await wiz.getByRole\('button', { name: 'Continue' }\).click\(\);
await page.getByTestId\('onboarding-seed'\).waitFor\(\);

const pairs = await page.locator\('[data-testid="onboarding-seed"] .grid > span'\).evaluateAll\(\(els\) =>
  els.map\(\(el\) => el.textContent.trim\(\)\)
\);
console.log\('SEED_CELLS', JSON.stringify\(pairs\)\);

await wiz.getByRole\('button', { name: 'I saved my phrase' }\).click\(\);
await page.getByTestId\('onboarding-phrase-check'\).waitFor\(\);

for \(let round = 0; round < 3; round++\) {
  const prompt = await page.locator\('[data-testid="onboarding-phrase-check"] p'\).first\(\).innerText\(\);
  console.log\('QUIZ', round, prompt\);
  const opts = page.getByTestId\('phrase-check-option'\);
  const n = await opts.count\(\);
  let solved = false;
  for \(let i = 0; i < n; i++\) {
    const before = await page.getByTestId\('onboarding-phrase-check'\).getAttribute\('data-round'\);
    const promptBefore = await page.locator\('[data-testid="onboarding-phrase-check"] p'\).first\(\).innerText\(\).catch\(\(\) => ''\);
    await opts.nth\(i\).click\(\);
    await page.waitForTimeout\(150\);
    const after = await page.getByTestId\('onboarding-phrase-check'\).getAttribute\('data-round'\).catch\(\(\) => null\);
    const promptAfter = await page.locator\('[data-testid="onboarding-phrase-check"] p'\).first\(\).innerText\(\).catch\(\(\) => ''\);
    if \(after === null || after !== before || promptAfter !== promptBefore\) { solved = true; console.log\('  solved with', i\); break; }
    if \(!\(await page.getByTestId\('onboarding-phrase-check'\).isVisible\(\).catch\(\(\) => false\)\)\) { solved = true; break; }
  }
  if \(!solved\) console.log\('  NOT SOLVED round', round\);
  if \(!\(await page.getByTestId\('onboarding-phrase-check'\).isVisible\(\).catch\(\(\) => false\)\)\) break;
}

await page.waitForTimeout\(500\);
console.log\('STEP AFTER QUIZ', await wiz.innerText\(\).then\(t => t.slice\(0, 200\)\).catch\(\(\) => 'no wizard'\)\);

const skip = wiz.getByRole\('button', { name: 'Skip' }\);
if \(await skip.count\(\)\) { await skip.first\(\).click\(\); await page.waitForTimeout\(400\); }
const skip2 = wiz.getByRole\('button', { name: 'Skip' }\);
if \(await skip2.count\(\)\) { await skip2.first\(\).click\(\); await page.waitForTimeout\(400\); }
const start = wiz.getByRole\('button', { name: 'Start messaging' }\);
if \(await start.count\(\)\) { await start.first\(\).click\(\); }
await page.waitForTimeout\(6000\);
console.log\('BODY', \(await page.locator\('body'\).innerText\(\)\).slice\(0, 1500\)\);
await page.screenshot\({ path: '.e2e/probe-2.png' }\);
await browser.close\(\);
EOF
